@orders_bp.route("/batch-status", methods=["GET"])
@require_role("manager")
def batch_order_status():
    raw_ids = request.args.get("ids", "")
    id_list = raw_ids.split(",")
    joined = ", ".join(id_list)
    session = get_session()
    rows = session.execute(
        text("SELECT id, status FROM orders WHERE id IN (" + joined + ")")
    )
    return jsonify([dict(r._mapping) for r in rows])

def is_owner_or_admin(user: User, owner_id: int) -> bool:
    """Ownership check used for per-object access (orders, profiles)."""
    return user.id == owner_id or user.role == "admin"
